import{_ as l,o as i,c as n,a2 as t}from"./chunks/framework.DBU8LMUS.js";const m=JSON.parse('{"title":"Polling","description":"","frontmatter":{"title":"Polling","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/polling.md","filePath":"latest/polling.md","lastUpdated":1786334463000}'),e={name:"latest/polling.md"};function r(o,a,s,u,g,p){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="polling" tabindex="-1">Polling <a class="header-anchor" href="#polling" aria-label="Permalink to &quot;Polling&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Polling</strong> adalah jajak pendapat ringan untuk mengetahui pendapat anggota komunitas. Setiap pengguna hanya dapat memberikan <strong>satu suara per polling</strong>. Hasil ditampilkan dalam bentuk persentase.</p><h2 id="melihat-daftar-polling" tabindex="-1">Melihat Daftar Polling <a class="header-anchor" href="#melihat-daftar-polling" aria-label="Permalink to &quot;Melihat Daftar Polling&quot;">​</a></h2><ol><li>Klik menu <strong>Polling</strong> pada navigasi.</li><li>Halaman menampilkan daftar polling dengan pertanyaan, pilihan jawaban, dan jumlah suara.</li><li>Polling yang sudah berakhir tidak lagi menerima suara.</li></ol><h2 id="memberikan-suara" tabindex="-1">Memberikan Suara <a class="header-anchor" href="#memberikan-suara" aria-label="Permalink to &quot;Memberikan Suara&quot;">​</a></h2><ol><li>Buka polling yang ingin diikuti.</li><li>Pilih salah satu <strong>pilihan jawaban</strong>.</li><li>Klik tombol <strong>Kirim Suara</strong>.</li><li>Hasil diperbarui dan menampilkan persentase setiap pilihan.</li></ol><div class="warning custom-block"><p class="custom-block-title">Satu Suara per Pengguna</p><p>Setiap pengguna hanya dapat memilih <strong>sekali</strong> untuk setiap polling. Setelah Anda memilih, tombol suara terkunci dan pilihan Anda ditandai.</p></div><h2 id="melihat-hasil-polling" tabindex="-1">Melihat Hasil Polling <a class="header-anchor" href="#melihat-hasil-polling" aria-label="Permalink to &quot;Melihat Hasil Polling&quot;">​</a></h2><p>Setelah memberikan suara (atau jika polling telah berakhir), hasil ditampilkan sebagai:</p><ul><li><strong>Persentase</strong> per pilihan jawaban.</li><li><strong>Jumlah suara</strong> per pilihan.</li><li><strong>Total suara</strong> keseluruhan.</li></ul><h2 id="membuat-polling" tabindex="-1">Membuat Polling <a class="header-anchor" href="#membuat-polling" aria-label="Permalink to &quot;Membuat Polling&quot;">​</a></h2><h3 id="membuka-formulir" tabindex="-1">Membuka Formulir <a class="header-anchor" href="#membuka-formulir" aria-label="Permalink to &quot;Membuka Formulir&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk.</li><li>Klik tombol <strong>Buat Polling</strong> pada halaman <strong>Polling</strong>.</li><li>Anda akan diarahkan ke halaman pembuatan polling.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><ol><li>Tulis <strong>pertanyaan</strong> polling.</li><li>Isi minimal dua <strong>pilihan jawaban</strong>.</li><li>(Opsional) tetapkan <strong>batas akhir</strong> polling.</li><li>Klik <strong>Simpan</strong>.</li></ol><h3 id="setelah-diterbitkan" tabindex="-1">Setelah Diterbitkan <a class="header-anchor" href="#setelah-diterbitkan" aria-label="Permalink to &quot;Setelah Diterbitkan&quot;">​</a></h3><p>Polling langsung tampil di halaman <strong>Polling</strong> dan dapat diikuti oleh seluruh pengguna yang masuk.</p><h2 id="menghapus-atau-menutup-polling" tabindex="-1">Menghapus atau Menutup Polling <a class="header-anchor" href="#menghapus-atau-menutup-polling" aria-label="Permalink to &quot;Menghapus atau Menutup Polling&quot;">​</a></h2><p>Polling dapat dihapus/ditutup oleh:</p><ul><li><strong>Pembuat</strong> polling.</li><li><strong>Admin</strong> dengan kemampuan <code>moderate_polls</code>.</li><li><strong>Super admin</strong>.</li></ul><ol><li>Buka polling yang ingin dikelola.</li><li>Klik tombol <strong>Hapus</strong> atau <strong>Tutup</strong>.</li><li>Konfirmasi tindakan.</li></ol><h2 id="tips-membuat-polling" tabindex="-1">Tips Membuat Polling <a class="header-anchor" href="#tips-membuat-polling" aria-label="Permalink to &quot;Tips Membuat Polling&quot;">​</a></h2><ul><li>Rumuskan pertanyaan secara singkat dan tidak ambigu.</li><li>Sediakan pilihan yang saling eksklusif.</li><li>Tetapkan batas akhir jika hasil hanya dibutuhkan dalam waktu tertentu.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/galeri">Galeri Kegiatan</a> untuk berbagi dokumentasi acara.</p>',25)])])}const d=l(e,[["render",r]]);export{m as __pageData,d as default};
